    const seg = fakeSegment();
    const capturedUser: string[] = [];
    const adapter: LLMAdapter = {
      async complete(msgs) {
        capturedUser.push(msgs.find(m => m.role === "user")!.content);
        return VALID_RESPONSE;
      },
