20	    globalState: {
21	      keys: () => Array.from(data.keys()),
22	      get: (k: string) => data.get(k),
23	      update: async (k: string, v: unknown) => { if (v === undefined) data.delete(k); else data.set(k, v); },
24	      setKeysForSync: () => {},
25	    },
26	  } as unknown as vscode.ExtensionContext;
27	}
28	
29	const VALID = JSON.stringify({
30	  kind: "logic",
31	  purpose: "A valid 20+char summary for this block's behavior.",
32	  flow: ["This block does something useful."],
33	  uses: [],
34	  produces: [],
35	  watch: [],
36	  concepts: [],
37	});
38	
39	suite("PrefetchQueue", () => {
40	  test("enqueueAll calls the adapter once per new segment and fills the store", async () => {
41	    const store = new ExplanationStore(ctx());
42	    let calls = 0;
43	    const adapter: LLMAdapter = {
44	      async complete() { calls++; return VALID; },
45	      async *completeStream() { calls++; yield VALID; },
46	    };
47	    const q = new PrefetchQueue({
48	      explanationStore: store,
49	      agentDeps: { adapter, promptsDir: PROMPTS_DIR },
50	      preset: "groq",
51	      promptVersion: "v1",
52	    });
53	    q.enqueueAll(vscode.Uri.file("/tmp/a.ts"), [seg("s1", 1), seg("s2", 20)]);
54	    await q.drain();
55	    assert.strictEqual(calls, 2);
56	    assert.ok(store.get("s1", "groq", "v1"));
57	    assert.ok(store.get("s2", "groq", "v1"));
58	    q.dispose();
59	    store.dispose();
60	  });
61	
62	  test("skips segments that already have a 'done' cache entry", async () => {
63	    const store = new ExplanationStore(ctx());
64	    store.set("s1", "groq", "v1", {
65	      segmentId: "s1",
66	      kind: "logic",
67	      purpose: "already cached — this block was prefetched in a prior session.",
68	      flow: [],
69	      uses: [],
70	      produces: [],
71	      watch: [],
72	      concepts: [],
73	      renderState: "done",
74	    });
75	    let calls = 0;
76	    const adapter: LLMAdapter = {
77	      async complete() { calls++; return VALID; },
78	      async *completeStream() { calls++; yield VALID; },
79	    };
80	    const q = new PrefetchQueue({
81	      explanationStore: store,
82	      agentDeps: { adapter, promptsDir: PROMPTS_DIR },
83	      preset: "groq",
84	      promptVersion: "v1",
85	    });
86	    q.enqueueAll(vscode.Uri.file("/tmp/a.ts"), [seg("s1", 1), seg("s2", 20)]);
87	    await q.drain();
88	    assert.strictEqual(calls, 1);
89	    q.dispose();
90	    store.dispose();
91	  });
92	
93	  test("re-enqueuing the same URI cancels the old batch and replaces it with the new one", async () => {
94	    const store = new ExplanationStore(ctx());
95	    let started = 0;
96	    let completed = 0;
97	    const adapter: LLMAdapter = {
98	      async complete() {
99	        started++;
100	        await new Promise(r => setTimeout(r, 50));
101	        completed++;
102	        return VALID;
103	      },
104	      async *completeStream() { yield VALID; },
105	    };
106	    const q = new PrefetchQueue({
107	      explanationStore: store,
108	      agentDeps: { adapter, promptsDir: PROMPTS_DIR },
109	      preset: "groq",
110	      promptVersion: "v1",
111	      concurrency: 1,
112	    });
113	    const uri = vscode.Uri.file("/tmp/a.ts");
114	    q.enqueueAll(uri, [seg("old-1", 1), seg("old-2", 10), seg("old-3", 20)]);
115	    await new Promise(r => setTimeout(r, 10));
116	    q.enqueueAll(uri, [seg("new-1", 1), seg("new-2", 10)]);
117	    await q.drain();
118	    // Only the new batch should be completed; the old batch beyond the first in-flight call is cancelled.
119	    assert.ok(store.get("new-1", "groq", "v1"));
120	    assert.ok(store.get("new-2", "groq", "v1"));
121	    q.dispose();
122	    store.dispose();
123	  });
124	
125	  test("disables itself for the session on AuthError; subsequent enqueueAll is a no-op", async () => {
126	    const store = new ExplanationStore(ctx());
127	    let calls = 0;
128	    const adapter: LLMAdapter = {
129	      async complete() { calls++; throw new AuthError("bad key"); },
130	      async *completeStream() { calls++; throw new AuthError("bad key"); },
131	    };
132	    const logs: string[] = [];
133	    const q = new PrefetchQueue({
134	      explanationStore: store,
135	      agentDeps: { adapter, promptsDir: PROMPTS_DIR },
136	      preset: "groq",
137	      promptVersion: "v1",
138	      logger: (m: string) => logs.push(m),
139	    });
140	    q.enqueueAll(vscode.Uri.file("/tmp/a.ts"), [seg("s1", 1), seg("s2", 20)]);
141	    await q.drain();
142	    assert.ok(calls >= 1 && calls <= 2);  // may stop after first, may finish both
143	    assert.ok(logs.some(l => l.includes("disabled")));
144	    calls = 0;
145	    q.enqueueAll(vscode.Uri.file("/tmp/b.ts"), [seg("s3", 1)]);
146	    await q.drain();
147	    assert.strictEqual(calls, 0);
148	    q.dispose();
149	    store.dispose();
150	  });
151	});
