  kind: "logic",
  purpose: "This is a valid summary after the retry — teaches the user what the block actually does.",
  flow: ["config is accessed"],
  uses: [],
  produces: [],
  watch: ["Assumes `config` is defined before this block runs."],
  concepts: [],
});

suite("explain() — input guard", () => {
