    const md = new vscode.MarkdownString("", true);
    md.supportHtml = false;
    md.isTrusted = false;
    if (partialSummary.length === 0) {
      md.appendMarkdown(`_Analyzing${dots} (${secs}s)_`);
    } else {
      md.appendMarkdown(partialSummary);
