    const store = new ExplanationStore(ctx());
    let calls = 0;
    const adapter: LLMAdapter = {
      async complete() { calls++; throw new AuthError("bad key"); },
      async *completeStream() { calls++; throw new AuthError("bad key"); },
    };
    const logs: string[] = [];
    const q = new PrefetchQueue({
