2	import { readUserConfig } from "../utils/config";
3	import { resolveBackend } from "../llm/presets";
4	import { OpenAICompatibleAdapter } from "../llm/openAiCompatibleAdapter";
5	import { isOllamaReachable } from "../llm/ollamaDetection";
6	import { FileTooLargeError, segment } from "../engine/segmenter";
7	import type { SegmentStore } from "../engine/segmentStore";
8	import {
9	  AuthError,
10	  CancelledError,
11	  MalformedResponseError,
12	  NetworkError,
13	  RateLimitError,
14	} from "../llm/adapter";
15	import {
16	  SegmentTooLargeError,
17	  ExplanationStreamError,
18	} from "../engine/explanationAgent";
19	import { runFirstRunWizard } from "./firstRunWizard";
20	
21	export function registerStartWalkthrough(
22	  context: vscode.ExtensionContext,
23	  store: SegmentStore,
24	  output: vscode.OutputChannel,
25	): vscode.Disposable {
26	  return vscode.commands.registerCommand("codewalk.startWalkthrough", async () => {
27	    const editor = vscode.window.activeTextEditor;
28	    if (!editor) {
29	      vscode.window.showInformationMessage("Open a file first to start CodeWalk.");
30	      return;
31	    }
32	    const document = editor.document;
33	    if (document.getText().trim().length === 0) {
34	      vscode.window.showInformationMessage("This file is empty — nothing to walk through.");
35	      return;
36	    }
37	
38	    const userConfig = await readUserConfig(context);
39	    let resolved;
40	    try {
41	      resolved = resolveBackend(userConfig);
42	    } catch (e) {
43	      showSettingsError(`CodeWalk config error: ${(e as Error).message}`);
44	      return;
45	    }
46	
47	    let finalResolved = resolved;
48	    const ollamaNotReady =
49	      resolved.backend === "ollama-local" && !(await isOllamaReachable(resolved.baseUrl));
50	    const cloudKeyMissing =
51	      resolved.backend !== "ollama-local" && resolved.requiresApiKey && !resolved.apiKey;
52	
53	    if (ollamaNotReady || cloudKeyMissing) {
54	      const wizardResult = await runFirstRunWizard(context);
55	      if (!wizardResult) return; // user cancelled the wizard
56	      finalResolved = wizardResult;
57	      if (
58	        finalResolved.backend === "ollama-local" &&
59	        !(await isOllamaReachable(finalResolved.baseUrl))
60	      ) {
61	        vscode.window.showErrorMessage(
62	          `CodeWalk can't reach Ollama at ${finalResolved.baseUrl}. Start Ollama and try again.`,
63	        );
64	        return;
65	      }
66	    }
67	
68	    store.clear(document.uri);
69	
70	    const adapter = new OpenAICompatibleAdapter({
71	      baseUrl: finalResolved.baseUrl,
72	      apiKey: finalResolved.apiKey,
73	      model: finalResolved.model,
74	      structuredOutputMode: finalResolved.structuredOutputMode,
75	    });
76	
77	    await vscode.window.withProgress(
78	      {
79	        location: vscode.ProgressLocation.Notification,
80	        title: "CodeWalk: Analyzing…",
81	        cancellable: true,
82	      },
83	      async (_progress, token) => {
84	        try {
85	          const promptsDir = context.asAbsolutePath("prompts");
86	          const segments = await segment(document, {
87	            adapter,
88	            promptsDir,
89	            logger: (msg) => output.appendLine(msg),
90	            token,
91	          });
92	          store.set(document.uri, segments);
93	          output.appendLine(`[success] ${segments.length} segments for ${document.fileName}`);
94	        } catch (e) {
95	          handleError(e, output);
96	        }
97	      },
98	    );
99	  });
100	}
101	
102	function showSettingsError(message: string): void {
103	  vscode.window
104	    .showErrorMessage(message, "Open Settings")
105	    .then((action) => {
106	      if (action === "Open Settings") {
107	        vscode.commands.executeCommand("workbench.action.openSettings", "codewalk");
108	      }
109	    });
110	}
111	
112	function handleError(e: unknown, output: vscode.OutputChannel): void {
113	  if (e instanceof CancelledError) {
114	    output.appendLine("[cancelled] user cancelled CodeWalk analysis");
115	    return;
116	  }
117	  if (e instanceof SegmentTooLargeError) {
118	    output.appendLine(
119	      `[SegmentTooLargeError] segmentId=${e.segmentId} lines=${e.lineCount}/${e.maxLines}`,
120	    );
121	    vscode.window.showWarningMessage(
122	      `CodeWalk skipped a block that's too large to explain (${e.lineCount} / ${e.maxLines} lines).`,
123	    );
124	    return;
125	  }
126	  if (e instanceof ExplanationStreamError) {
127	    output.appendLine(
128	      `[ExplanationStreamError] cause=${e.cause} message=${e.message}`,
129	    );
130	    vscode.window.showErrorMessage(
131	      "CodeWalk couldn't finish the explanation — the connection dropped. Try again.",
132	    );
133	    return;
134	  }
135	  if (e instanceof NetworkError) {
136	    output.appendLine(`[NetworkError] ${e.message}`);
137	    vscode.window.showErrorMessage(
138	      "CodeWalk couldn't reach the LLM. Check your connection and backend URL.",
139	    );
140	  } else if (e instanceof AuthError) {
141	    output.appendLine(`[AuthError] ${e.message}`);
142	    showSettingsError("CodeWalk's API key was rejected. Open settings to update it.");
143	  } else if (e instanceof RateLimitError) {
144	    output.appendLine(`[RateLimitError] ${e.message}${e.retryAfter ? ` retry-after: ${e.retryAfter}s` : ""}`);
145	    vscode.window.showErrorMessage("CodeWalk hit a rate limit. Try again in a moment.");
146	  } else if (e instanceof MalformedResponseError) {
147	    output.appendLine(`[MalformedResponseError] ${e.message}\nRaw: ${e.rawResponse ?? "<none>"}`);
148	    showSettingsError(
149	      "CodeWalk couldn't parse the model's response. Try a more capable model in settings.",
150	    );
151	  } else if (e instanceof FileTooLargeError) {
152	    output.appendLine(`[FileTooLargeError] ${e.message}`);
153	    vscode.window.showWarningMessage(
154	      `CodeWalk can't analyze files over ${e.maxLines} lines yet. This file has ${e.lineCount}.`,
155	    );
156	  } else {
157	    const err = e as Error;
158	    output.appendLine(`[Unhandled] ${err.stack ?? err.message ?? String(e)}`);
159	    vscode.window.showErrorMessage(
160	      "CodeWalk encountered an unexpected error. See the Output panel.",
161	    );
162	  }
163	}
