      || e.affectsConfiguration("codewalk.baseUrl")
      || e.affectsConfiguration("codewalk.explanation.prefetchOnSegmentation")
      || e.affectsConfiguration("codewalk.explanation.prefetchNeighborsOnClick")
    ) {
