    const err = e as Error;
    output.appendLine(`[Unhandled] ${err.stack ?? err.message ?? String(e)}`);
    vscode.window.showErrorMessage(
      "CodeWalk encountered an unexpected error. See the Output panel.",
    );
  }
}

