    const store = new SegmentStore();
    const ws = new WalkSession(store);
    const uri = vscode.Uri.file("/tmp/a.ts");
    ws.addFile(uri);
    ws.addFile(uri);
    assert.strictEqual(ws.state().fileQueue.length, 1);
    ws.dispose();
    store.dispose();
  });

