  test("removeFile shrinks the queue and adjusts activeFileIndex", () => {
    const store = new SegmentStore();
    const ws = new WalkSession(store);
    const a = vscode.Uri.file("/tmp/a.ts");
    const b = vscode.Uri.file("/tmp/b.ts");
